class Solution:
    def numberOfSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        cnt = [0] * 26
        l = bad = 0
        for r, ch in enumerate(s):
            cnt[ord(ch) - 97] += 1
            while cnt[ord(ch) - 97] >= k:
                cnt[ord(s[l]) - 97] -= 1
                l += 1
            bad += r - l + 1
        return n * (n + 1) // 2 - bad

c.cpp:
class Solution {
public:
    long long numberOfSubstrings(string s, int k) {
        long long n = s.size(), bad = 0;
        int cnt[26] = {0}, l = 0;
        for (int r = 0; r < n; r++) {
            cnt[s[r] - 'a']++;
            while (cnt[s[r] - 'a'] >= k) { cnt[s[l++] - 'a']--; }
            bad += r - l + 1;
        }
        return n * (n + 1) / 2 - bad;
    }
};

