class Solution {
    public long numberOfSubstrings(String s, int k) {
        int n = s.length(), l = 0;
        int[] cnt = new int[26];
        long bad = 0;
        for (int r = 0; r < n; r++) {
            cnt[s.charAt(r) - 'a']++;
            while (cnt[s.charAt(r) - 'a'] >= k) { cnt[s.charAt(l) - 'a']--; l++; }
            bad += r - l + 1;
        }
        return (long) n * (n + 1) / 2 - bad;
    }
}

