var numberOfSubstrings = function(s, k) {
    const n = s.length, cnt = new Array(26).fill(0);
    let l = 0, bad = 0;
    for (let r = 0; r < n; r++) {
        cnt[s.charCodeAt(r) - 97]++;
        while (cnt[s.charCodeAt(r) - 97] >= k) { cnt[s.charCodeAt(l) - 97]--; l++; }
        bad += r - l + 1;
    }
    return n * (n + 1) / 2 - bad;
};
